insert into sources (code, name, description, kind, base_url, docs_url, auth, countries, regions, license, attribution, retention_days, redistributable, published_by) values
  ('bag', 'Basisregistratie Adressen en Gebouwen (BAG), OGC API of PDOK', 'The Dutch base register of addresses and buildings kept by the municipalities and published by the Kadaster: every address, every addressable object and every building (pand) with its identifier, footprint, year of construction and status.', 'api', 'https://api.pdok.nl/kadaster/bag/ogc/v2', 'https://api.pdok.nl/kadaster/bag/ogc/v2?f=html', 'none', array['NL']::text[], '{}'::text[], 'Public Domain Mark 1.0', 'Kadaster — Basisregistratie Adressen en Gebouwen (BAG)', null, true, 'pack:nl'),
  ('cbs', 'CBS — Statistics Netherlands', 'The statistics office''s tables and open data, among them the municipal division of each year with the 4-digit municipality codes.', 'file', 'https://www.cbs.nl/', 'https://www.cbs.nl/nl-nl/over-ons/website/copyright', 'none', array['NL']::text[], '{}'::text[], 'CC-BY-4.0', 'Bron: CBS', null, true, 'pack:nl'),
  ('kvk_handelsregister', 'Handelsregister of the Kamer van Koophandel (KvK)', 'The Dutch Business Register of enterprises and legal persons, searched by KvK number.', 'registry', 'https://www.kvk.nl/', null, 'none', array['NL']::text[], '{}'::text[], 'Terms not stated', null, null, false, 'pack:nl'),
  ('nl_begrippencode_elektriciteit', 'Begrippencode elektriciteit (ACM)', 'The definitions code of the Dutch electricity codes set by the Autoriteit Consument en Markt: the imbalance settlement period, the bidding zone, the voltage levels, a small and a large connection.', 'text', 'https://wetten.overheid.nl/BWBR0037938/2025-12-20', null, 'none', array['NL']::text[], '{}'::text[], 'Public domain (Auteurswet, article 11: laws and decisions of public authorities)', null, null, true, 'pack:nl'),
  ('nl_energiewet', 'Energiewet (Wet van 11 december 2024, Stb. 2025, 12)', 'The Dutch energy act that replaced the Elektriciteitswet 1998 and the Gaswet on 1 January 2026: the definitions of an active customer and an energy community (article 1.1), energy sharing (article 2.30) and netting for a small connection (article 2.31). Consolidated version in force from 1 July 2026 read.', 'text', 'https://wetten.overheid.nl/BWBR0050714/2026-07-01', null, 'none', array['NL']::text[], '{}'::text[], 'Public domain (Auteurswet, article 11: laws and decisions of public authorities)', null, null, true, 'pack:nl'),
  ('nl_entsoe_eic_codes', 'ENTSO-E — list of Y EIC codes (areas)', 'The list of area codes of the European electricity market, with their functions: bidding zone, control area, scheduling area.', 'text', 'https://eepublicdownloads.blob.core.windows.net/cio-lio/csv/Y_eicCodes.csv', null, 'none', array['NL']::text[], '{}'::text[], 'Terms not stated', null, null, false, 'pack:nl'),
  ('nl_entsoe_eic_parties', 'ENTSO-E — list of X EIC codes (parties)', 'The list of party codes of the European electricity market: system operators, suppliers, traders.', 'text', 'https://eepublicdownloads.blob.core.windows.net/cio-lio/csv/X_eicCodes.csv', null, 'none', array['NL']::text[], '{}'::text[], 'Terms not stated', null, null, false, 'pack:nl'),
  ('nl_eurostat_business_prices', 'Eurostat — electricity prices components for non-household consumers, annual (nrg_pc_205_c)', 'Yearly electricity prices of non-household consumers by consumption band and component.', 'text', 'https://ec.europa.eu/eurostat/databrowser/view/nrg_pc_205_c/default/table', null, 'none', array['NL']::text[], '{}'::text[], 'CC-BY-4.0', '© European Union, Eurostat', null, true, 'pack:nl'),
  ('nl_eurostat_household_prices', 'Eurostat — electricity prices components for household consumers, annual (nrg_pc_204_c)', 'Yearly electricity prices of households by consumption band and component: energy and supply, network costs, taxes and levies, VAT.', 'text', 'https://ec.europa.eu/eurostat/databrowser/view/nrg_pc_204_c/default/table', null, 'none', array['NL']::text[], '{}'::text[], 'CC-BY-4.0', '© European Union, Eurostat', null, true, 'pack:nl'),
  ('nl_gebiedsindelingscode_elektriciteit', 'Gebiedsindelingscode elektriciteit (ACM)', 'The code that sets the area of each Dutch electricity grid operator: the national high-voltage grid (article 3), the regional high-voltage grids (article 4), the medium- and low-voltage grids by province, municipality and district (article 5).', 'text', 'https://wetten.overheid.nl/BWBR0037943/2023-12-13', null, 'none', array['NL']::text[], '{}'::text[], 'Public domain (Auteurswet, article 11: laws and decisions of public authorities)', null, null, true, 'pack:nl'),
  ('nl_netcode_elektriciteit', 'Netcode elektriciteit (ACM)', 'The grid code of the Dutch electricity networks set by the Autoriteit Consument en Markt: how a grid operator builds the meter data of balance responsibility (article 10.17) and the voltage levels it reports by (article 8.1).', 'text', 'https://wetten.overheid.nl/BWBR0037940/2025-12-31', null, 'none', array['NL']::text[], '{}'::text[], 'Public domain (Auteurswet, article 11: laws and decisions of public authorities)', null, null, true, 'pack:nl'),
  ('nl_stb_2025_17', 'Wet van 18 december 2024 ter uitvoering van de beëindiging van de salderingsregeling voor elektriciteit (Stb. 2025, 17)', 'The act that repeals article 2.31 of the Energiewet (netting) and adds to article 2.34 a reasonable remuneration for what an active customer feeds back, from 1 January 2027 (article V).', 'text', 'https://zoek.officielebekendmakingen.nl/stb-2025-17.html', null, 'none', array['NL']::text[], '{}'::text[], 'Public domain (Auteurswet, article 11: laws and decisions of public authorities)', null, null, true, 'pack:nl'),
  ('nl_wet_omzetbelasting', 'Wet op de omzetbelasting 1968', 'The Dutch VAT act: the general rate (article 9, first paragraph) and the goods and services of the reduced rate (table I), among which electricity is not.', 'text', 'https://wetten.overheid.nl/BWBR0002629/2026-01-01', null, 'none', array['NL']::text[], '{}'::text[], 'Public domain (Auteurswet, article 11: laws and decisions of public authorities)', null, null, true, 'pack:nl'),
  ('pdok_locatieserver', 'PDOK Locatieserver', 'The national geocoding service of PDOK: free search, suggest and reverse lookup of addresses, postal codes, streets, places, municipalities and parcels, built from the BAG and other base registers. An address it returns carries its BAG identifiers, its CBS municipality code and its province. No connector of this repository reads it yet.', 'api', 'https://api.pdok.nl/bzk/locatieserver/search/v3_1/free', null, 'none', array['NL']::text[], '{}'::text[], 'Public Domain Mark 1.0 for the BAG data it returns, as the BAG API of PDOK states; the terms of the service itself not verified', '© Kadaster / PDOK', null, true, 'pack:nl'),
  ('threedbag', '3DBAG', 'Every building of the BAG as a 3D model at several levels of detail, in CityJSON among other formats, keyed by its BAG building identifier; read by the format library `cityjson`.', 'file', 'https://3dbag.nl/', 'https://docs.3dbag.nl/en/copyright/', 'none', array['NL']::text[], '{}'::text[], 'CC-BY-4.0', '3DBAG by the 3D geoinformation research group and 3DGI', null, true, 'pack:nl')
