insert into identifier_schemes (code, name, description, pattern, url_template, source_code, icd, published_by) values
  ('bag_nummeraanduiding', 'BAG address (nummeraanduiding)', 'The 16-digit identifier of an address in the Basisregistratie Adressen en Gebouwen (BAG): the code of the municipality that created it, the object type 20, and a 10-digit serial number. The first four digits keep the municipality of creation after a merger.', '^[0-9]{4}20[0-9]{10}$', 'https://bag.basisregistraties.overheid.nl/bag/id/nummeraanduiding/{value}', 'bag', null, 'pack:nl'),
  ('bag_pand', 'BAG building (pand)', 'The 16-digit identifier of a building in the BAG: the code of the municipality that created it, the object type 10, and a 10-digit serial number. The 3DBAG keys its 3D models by the same identifier.', '^[0-9]{4}10[0-9]{10}$', null, 'bag', null, 'pack:nl'),
  ('cbs_gemeentecode', 'CBS municipality code (gemeentecode)', 'The 4-digit code of a Dutch municipality given by Statistics Netherlands (CBS), written without the GM prefix of its statistical tables: the level at which a distribution operator''s area, local planning rules and most datasets are decided. It changes when municipalities merge. It is not the postal code.', '^[0-9]{4}$', null, 'cbs', null, 'pack:nl'),
  ('kvk_number', 'KvK number', 'The 8-digit number of an enterprise or a legal person in the Dutch Business Register (Handelsregister) of the Chamber of Commerce (Kamer van Koophandel).', '^[0-9]{8}$', null, 'kvk_handelsregister', '0106', 'pack:nl')
