-- grid.support_schemes: 1. Who a scheme supports, for how long, and when it stops at negative prices.
insert into grid.support_schemes (code, country, name, kind, allocation, device_types, min_power_kw, max_power_kw, duration_years, negative_price_rules, source_code, reference, valid_from, valid_to, published_by) values
  ('nl_salderingsregeling', 'NL', 'Salderingsregeling', 'net_metering', 'open_window', '{}'::text[], null, null, null, '[]'::jsonb, 'nl_energiewet', 'Article 2.31: for a final customer with a small connection (3 x 80 A or less, article 1.1) who has no feed-back contract with another market party than its supplier, the supplier deducts what is fed in from what is taken, up to what is taken, for renewable electricity (up to 5 000 kWh fed in for non-renewable electricity), and pays a reasonable, non-negative remuneration for the surplus. Repealed from 1 January 2027 by the act of 18 December 2024 (Stb. 2025, 17, article I, B, and article V), which from then gives an active customer a reasonable remuneration for what it feeds back, not below 50 % of its agreed supply price until 1 January 2030 (new article 2.34, ninth paragraph). The netting of the Elektriciteitswet 1998 before 2026 was not read for this pack', '2026-01-01'::date, '2027-01-01'::date, 'pack:nl')
on conflict (code) do update set
  country              = excluded.country,
  name                 = excluded.name,
  kind                 = excluded.kind,
  allocation           = excluded.allocation,
  device_types         = excluded.device_types,
  min_power_kw         = excluded.min_power_kw,
  max_power_kw         = excluded.max_power_kw,
  duration_years       = excluded.duration_years,
  negative_price_rules = excluded.negative_price_rules,
  source_code          = excluded.source_code,
  reference            = excluded.reference,
  valid_from           = excluded.valid_from,
  valid_to             = excluded.valid_to
where support_schemes.published_by = excluded.published_by;

-- defaults: 14 value(s), 2 for a condition. What parameter_of() answers
-- for a participant of the country when nothing nearer gives a value.
do $seed$
declare
  refused text;
begin
  with pack (attribute_type, region, condition, value, unit, valid_from, valid_to, source_code, reference, quality) as (
    values
      ('bidding_zone'::text, null::text, '{}'::jsonb, '"10YNL----------L"'::jsonb, 'code'::text, '2026-11-07'::date, null::date, 'nl_entsoe_eic_codes'::text, 'Row 10YNL----------L, display name NL, functions Bidding Zone, Control Area, LFC Area, LFC Block, Member State, Scheduling Area'::text, 'published'::text),
      ('control_area'::text, null::text, '{}'::jsonb, '"10YNL----------L"'::jsonb, 'code'::text, '2026-11-07'::date, null::date, 'nl_entsoe_eic_codes'::text, 'Row 10YNL----------L, function Control Area, display name NL'::text, 'published'::text),
      ('energy_price_business'::text, null::text, '{}'::jsonb, '116.9'::jsonb, 'EUR-PER-MegaW-HR'::text, '2024-01-01'::date, '2025-01-01'::date, 'nl_eurostat_business_prices'::text, 'nrg_pc_205_c, Netherlands, 2024, band MWH2000-19999, component NRG_SUP: 0.1169 EUR/kWh'::text, 'published'::text),
      ('energy_price_business'::text, null::text, '{}'::jsonb, '101'::jsonb, 'EUR-PER-MegaW-HR'::text, '2025-01-01'::date, null::date, 'nl_eurostat_business_prices'::text, 'nrg_pc_205_c, Netherlands, 2025, band MWH2000-19999, component NRG_SUP: 0.1010 EUR/kWh'::text, 'published'::text),
      ('energy_price_household'::text, null::text, '{}'::jsonb, '170.2'::jsonb, 'EUR-PER-MegaW-HR'::text, '2024-01-01'::date, '2025-01-01'::date, 'nl_eurostat_household_prices'::text, 'nrg_pc_204_c, Netherlands, 2024, band KWH2500-4999, component NRG_SUP: 0.1702 EUR/kWh'::text, 'published'::text),
      ('energy_price_household'::text, null::text, '{}'::jsonb, '146.7'::jsonb, 'EUR-PER-MegaW-HR'::text, '2025-01-01'::date, null::date, 'nl_eurostat_household_prices'::text, 'nrg_pc_204_c, Netherlands, 2025, band KWH2500-4999, component NRG_SUP: 0.1467 EUR/kWh'::text, 'published'::text),
      ('grid_fees_and_taxes'::text, null::text, '{}'::jsonb, '64.3'::jsonb, 'EUR-PER-MegaW-HR'::text, '2024-01-01'::date, '2025-01-01'::date, 'nl_eurostat_household_prices'::text, 'nrg_pc_204_c, Netherlands, 2024, band KWH2500-4999, components NETC 0.1015 and TAX_FEE_LEV_CHRG -0.0372 EUR/kWh, VAT excluded; a mean over the band, in which the fixed energy tax credit per connection (heffingskorting) outweighs part of the energy tax, so a kWh saved at the margin saves more than this figure'::text, 'published'::text),
      ('grid_fees_and_taxes'::text, null::text, '{}'::jsonb, '99.9'::jsonb, 'EUR-PER-MegaW-HR'::text, '2025-01-01'::date, null::date, 'nl_eurostat_household_prices'::text, 'nrg_pc_204_c, Netherlands, 2025, band KWH2500-4999, components NETC 0.1135 and TAX_FEE_LEV_CHRG -0.0136 EUR/kWh, VAT excluded; a mean over the band, in which the fixed energy tax credit per connection (heffingskorting) outweighs part of the energy tax, so a kWh saved at the margin saves more than this figure'::text, 'published'::text),
      ('imbalance_settlement_period'::text, null::text, '{}'::jsonb, '"PT15M"'::jsonb, 'ISO8601-duration'::text, '2026-11-07'::date, null::date, 'nl_begrippencode_elektriciteit'::text, 'Definition of onbalansverrekeningsperiode: the time unit of imbalance settlement, 15 minutes, by clock quarter-hour'::text, 'published'::text),
      ('metering_step'::text, null::text, '{}'::jsonb, '"PT15M"'::jsonb, 'ISO8601-duration'::text, '2026-11-07'::date, null::date, 'nl_netcode_elektriciteit'::text, 'Article 10.17, third and tenth paragraphs: the grid operator builds the meter data of balance responsibility per imbalance settlement period (15 minutes, Begrippencode elektriciteit) from the meters it reads remotely at small connections whose allocation method is slimme-meter-allocatie; a small connection allocated by profile (profielallocatie) has no quarter-hour readings'::text, 'published'::text),
