      ('sharing_settlement_period'::text, null::text, '{"project_kind":"nl_energiegemeenschap"}'::jsonb, '"PT15M"'::jsonb, 'ISO8601-duration'::text, '2026-01-01'::date, null::date, 'nl_energiewet'::text, 'Article 2.30, first paragraph, d: a connected party within an energy community shares its electricity per imbalance settlement period, 15 minutes by the Begrippencode elektriciteit'::text, 'published'::text),
      ('vat_rate_electricity'::text, null::text, '{}'::jsonb, '0.21'::jsonb, 'UNITLESS'::text, '2023-01-01'::date, null::date, 'nl_wet_omzetbelasting'::text, 'Article 9, first paragraph: the tax is 21 percent; electricity is not among the goods and services of table I (9 percent). Held from 1 January 2023; the rates of earlier years were not read'::text, 'published'::text),
      ('voltage_levels'::text, null::text, '{}'::jsonb, '[{"code":"lv","name":"Laagspanning","min_kv":0,"max_kv":1},{"code":"mv","name":"Middenspanning","min_kv":1,"max_kv":35},{"code":"hv","name":"Hoogspanning","min_kv":35,"max_kv":150},{"code":"ehv","name":"Extra hoogspanning","min_kv":150,"max_kv":380}]'::jsonb, 'KiloV'::text, '2026-11-07'::date, null::date, 'nl_netcode_elektriciteit'::text, 'Article 8.1, first paragraph: the levels a grid operator reports its interruptions by — up to 1 kV; above 1 kV up to 35 kV; above 35 kV up to 150 kV; 220 kV and 380 kV. The Begrippencode elektriciteit defines low voltage as up to 1 kV (alternating current) and a medium-voltage grid as above 1 kV up to 35 kV'::text, 'published'::text)
  ),
  problems (problem) as (
    select format('attribute_type_unknown: %s is not an attribute_types code', p.attribute_type)
      from pack p
     where not exists (select 1 from attribute_types d where d.code = p.attribute_type)
    union all
    select format('unit_mismatch: %s is stored in %s and the pack says %s', p.attribute_type, u.unit, p.unit)
      from pack p
      join attribute_types d on d.code = p.attribute_type
      join quantities q on q.code = d.quantity_code
      cross join lateral (select quantity_unit(q.code, (select c.currency from countries c where c.code = 'NL')) as unit) u
     where u.unit <> p.unit
    union all
    select format('value_edited: %s%s from %s holds %s and the pack says %s; close it with valid_to and add a row',
                  p.attribute_type, coalesce(' (' || nullif(concat_ws(', ', p.region, nullif(p.condition, '{}')::text), '') || ')', ''), p.valid_from,
                  coalesce(x.value::text, 'null'), coalesce(p.value::text, 'null'))
      from pack p
      join defaults x
        on x.country = 'NL' and x.attribute_type = p.attribute_type
       and x.region is not distinct from p.region and x.valid_from = p.valid_from
       and x.condition = p.condition
     where x.value is distinct from p.value
  ),
  written as (
    insert into defaults (attribute_type, country, region, condition, value, valid_from, valid_to,
                          source_code, reference, quality, published_by)
    select p.attribute_type, 'NL', p.region, p.condition, p.value, p.valid_from, p.valid_to,
           p.source_code, p.reference, p.quality, 'pack:nl'
      from pack p
     where not exists (select 1 from problems)
    on conflict (country, region, attribute_type, condition, valid_from) do update set
      valid_to    = excluded.valid_to,
      source_code = excluded.source_code,
      reference   = excluded.reference,
      quality     = excluded.quality
    returning 1
  )
  select string_agg(problem, '; ' order by problem) into refused from problems;
  if refused is not null then
    raise exception '%', refused;
  end if;
end
$seed$;
